import pathlib,hashlib,json
base=pathlib.Path(__file__).resolve().parent; root=base.parents[1]
groups={
'scripts/generate_defense_package.py':[(1,8,'Path وshutil وzipfile قياسية؛ ROOT وتحميل الإعداد والتشغيل والبصمات والتخزين داخلية.'),(11,21,'copy_project تنسخ الشيفرة والإعدادات والوثائق والعجلات واللقطات والتشغيل وآثار الاختبارات والبيئة والمؤشر إلى الوجهة؛ dirs_exist_ok يسمح بالدمج مع ملفات موجودة وقد يستبدل نسخاً، فلا يعني إنشاء حزمة معزولة تلقائياً.'),(24,31,'archive_package تنشئ backups وتفتح ZIP باسم التشغيل بوضع w وتضيف الملفات دون ضغط؛ وضع w يمكنه استبدال ملف موجود بالاسم نفسه، ولذلك هذا السكربت أقدم من ضمان عدم الاستبدال في حزمة CPU.'),(32,36,'تفحص CRC باستخدام testzip وتكتب JSON لبصمة ZIP ثم تعيد المسار؛ النسخة على القرص نفسه ولا تثبت نسخة خارجية.'),(39,50,'main تحدد مجلد defense_package داخل الجذر وتتحقق من احتوائه وتنسخ تجربة full وتحسب بصمات الملفات عدا manifest ثم تكتب فهرساً وتحزم وتطبع؛ لها آثار نسخ وكتابة.'),(53,54,'حارس التنفيذ المباشر يستدعي main؛ لم يشغل هنا.')],
'scripts/package_cpu_defense.py':[(1,16,'توثيق واستيرادات قياسية، وROOT، وdigest لحساب SHA-256 لملف ثنائي.'),(19,28,'main تقبل archive وتفرض امتداد ZIP ووجوده داخل الجذر، وتنشئ الأب وترفض أرشيفاً موجوداً؛ لا تنفذ الحزم أثناء التوثيق.'),(29,37,'تحدد مجلد بناء زمني جديداً، وتقرأ إيصال النشر وتؤكد نجاحه ووجود 90 عجلة وtorch CPU وعدم وجود عجلات CUDA/NVIDIA؛ assertions قد تُعطل في Python المحسن.'),(38,50,'تنسخ المصدر والوثائق والإعدادات والعجلات واللقطات وجميع تشغيلات البحث والتحقق وآثار البيئة والاختبارات ومؤشرات latest، مع استبعاد ذاكرات Python من المصدر.'),(51,63,'تنسخ إيصالات نشر مختارة عدا إيصالات الإصدار الخارجي، وصور وإيصالات متصفح فقط من المجلدات المطابقة.'),(64,71,'تقرأ بصمات الأدلة الأصلية وتتحقق من وجودها وتطابقها في staging، ثم تحصر الملفات وأحجامها وبصماتها وتكتب CPU_PACKAGE_MANIFEST. هذه سلامة مقابل baseline المسجل.'),(72,80,'ترفض ملف pending موجوداً وتفتح ZIP حصرياً وتضيف الملفات باختيار ضغط بحسب الامتداد؛ لا تضغط عجلات وصوراً وأنواعاً مضغوطة مسبقاً.'),(81,86,'تفحص CRC وقائمة الأعضاء وبصمة كل عضو مقابل الفهرس؛ قد تستهلك الذاكرة عند قراءة عضو كبير كاملاً.'),(87,93,'تعيد تسمية pending إلى الأرشيف، وتحسب بصمته وتكتب ملف sha256 وإيصال package.json وتطبع التقرير؛ يلاحظ التعليق أن rename في Windows يرفض وجهة موجودة.'),(96,97,'حارس التنفيذ يستدعي main.')],
'scripts/package_scientific_validation.py':[(1,13,'توثيق وأدوات قياسية للوسائط والبيانات المضمنة والبصمات وHTML وZIP، وPillow خارجية، ووظائف المشروع.'),(16,23,'EmbeddedImages يرث HTMLParser ويجمع قيم src من كل عنصر img؛ يفترض وجود السمة.'),(26,36,'verify_offline_page تحلل HTML المحفوظ وتقارن الصور الخمس المضمنة بايتاً بملفات PNG المفروزة وتطلب Pillow التحقق من صيغتها، ثم تكتب تقريراً. فحص الصور المحددة لا يمسح كل أشكال الاتصالات أو يثبت بمفرده أن الصفحة بأكملها لا تحتاج شبكة.'),(39,47,'snapshot_source تنشئ source_snapshot جديداً وتنسخ ملفات Python وYAML من مجلدات محددة مع إعدادات وتقارير مرجعية، محافظة على المسارات؛ لا تستخدم نسخة المصدر هذه كتطبيق نشط.'),(50,57,'package_addendum تحصر الملفات وتكتب أحجامها وبصماتها ثم تفتح ZIP إضافياً حصرياً وتضيف الملفات والفهرس؛ تفترض وجود مجلد backups.'),(58,66,'تفحص CRC وعدد الأعضاء وطول وبصمة كل ملف ثم تكتب إيصال الأرشيف وتطبع بصمته؛ هذه آثار كتابة لا تنشئ نسخة خارج القرص.'),(69,75,'main تقرأ مجلد الوجهة وتتحقق من صفحة offline وتنسخ الشيفرة وتبني الملحق بهذا الترتيب؛ كلها آثار تنفيذ ولم تحدث هنا.'),(78,79,'حارس التنفيذ المباشر.')]
}
manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); digest=hashlib.sha256(raw).hexdigest(); name=path.replace('/','_')+'.md'; out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','لم تنفذ عمليات النسخ أو الحزم في جلسة التوثيق.','']
 for a,b,d in entries: out += [f'## الأسطر {a}–{b}','','```python',*src[a-1:b],'```','',d,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8'); manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'يدوية غير مستقلة','quote_verification':'آلي'}
(base/'packaging_docs_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')

